fn find_nth_properties_block<'a>(class_node: Node<'a>, index: usize) -> Option<Node<'a>> {
    let mut count = 0;
    let child_count = class_node.child_count();
    for i in 0..child_count {
        let child = class_node.child(i)?;
        if child.kind() == "properties" {
            if count == index {
                return Some(child);
            }
            count += 1;
        }
    }
    None
}
```

