+    fn all_descendants_of_kind<'a>(node: Node<'a>, kind: &str) -> Vec<Node<'a>> {
+        let mut result = Vec::new();
+        if node.kind() == kind {
+            result.push(node);
+        }
+        let mut cursor = node.walk();
+        for child in node.children(&mut cursor) {
+            result.extend(all_descendants_of_kind(child, kind));
+        }
+        result
